    m = d.month if d else None
    y = d.year if d else None

    if y == year and m == 1:
        spot = 'Athens'
    elif y == year and m == 4:
        spot = 'Seoul'
    else:
        spot = 'Paris'

    classified_paths[spot].append((p, info.get('created_at')))

for spot, items in classified_paths.items():
    print(spot, 'count', len(items))
    # print basenames only for brevity
    for src, created in items:
        print(' ', os.path.basename(src), created)

