access_token = apis.file_system.login(username=profile['email'], password=file_pw)['access_token']

vac_dir = '~/photographs/vacations/'
spots = ['Athens','Seoul','Paris']

# Ensure subdirectories exist (in case they were not created)
for spot in spots:
    dest_dir = os.path.join(vac_dir, spot)
    exists = apis.file_system.directory_exists(access_token=access_token, directory_path=dest_dir).get('exists', False)
    print('dest_dir', spot, 'exists', exists)
    if not exists:
        print(apis.file_system.create_directory(access_token=access_token, directory_path=dest_dir, recursive=True, allow_if_exists=True))

# Count current files in each subdirectory
for spot in spots:
    dest_dir = os.path.join(vac_dir, spot) + '/'  # API seems to like trailing slash in examples
    try:
        dest_files = apis.file_system.show_directory(access_token=access_token, directory_path=dest_dir, entry_type='files', recursive=False)
        print('dest', spot, 'file_count', len(dest_files))
    except Exception as e:
        print('dest', spot, 'error', e)

# List root files
root_files = apis.file_system.show_directory(access_token=access_token, directory_path=vac_dir, entry_type='files', recursive=False)
print('root_files_count', len(root_files))

year = datetime.now().year

def parse_dt(s):
    if not s:
        return None
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')

classified = {'Athens': [], 'Seoul': [], 'Paris': []}
for src_path in root_files:
    info = apis.file_system.show_file(access_token=access_token, file_path=src_path)
    dt = parse_dt(info.get('created_at'))
    if dt and dt.year == year and dt.month == 1:
        spot = 'Athens'
    elif dt and dt.year == year and dt.month == 4:
        spot = 'Seoul'
    else:
        spot = 'Paris'
    classified[spot].append(os.path.basename(src_path))

print('classification_year', year)
for spot in spots:
    print(spot, 'count', len(classified[spot]))
    print(' ', sorted(classified[spot]))

task = apis.supervisor.show_active_task();
print('active_task_answer', task.get('answer'));
if task.get('answer') == '<<NOT_GIVEN>>':
    print(apis.supervisor.complete_task())
else:
    print(apis.supervisor.complete_task(answer=task.get('answer')))
